-- ==== src/00_header.lua ====
-- Holo: watch parties for Worms Ultimate Mayhem. Client-only. This file is generated by tools/build_lua.py from
-- src/*.lua (name order); edit the fragments, not this file. Every fragment is one do ... end block that fills one
-- of the namespace tables below, so the chunk keeps far fewer than 200 top-level locals.
local U, CFG, NET, PARTY, QUEUE, LAYOUT, SKIN, W, PUI, SETUP, MAIN = {}, {}, {}, {}, {}, {}, {}, {}, {}, {}, {}
local VERSION = "1.0.0"

if not (wum and wum.media and wum.peer and wum.input and wum.draw and wum.draw.hudNine) then
  wum.log.warn("Holo needs Melange 0.12.0 or later (wum.media, wum.peer, wum.input and wum.draw.hudNine); not started")
  return
end

-- Tests read the namespaces through this hook; the real game never defines it.
if wum._holoTest then
  wum._holoTest.ns = {U = U, CFG = CFG, NET = NET, PARTY = PARTY, QUEUE = QUEUE, LAYOUT = LAYOUT, SKIN = SKIN,
    W = W, PUI = PUI, SETUP = SETUP, MAIN = MAIN}
end

do
  -- Log with a level: U.log("info", ...). Unknown levels fall back to info.
  function U.log(level, ...)
    local f = wum.log[level] or wum.log.info
    f("[holo]", ...)
  end

  -- In-file bus. U.emit runs the listeners of a name synchronously, in subscription order; a listener that raises
  -- is logged and skipped, it never stops the others.
  local listeners = {}

  function U.on(name, fn)
    local l = listeners[name]
    if not l then
      l = {}
      listeners[name] = l
    end
    l[#l + 1] = fn
    return fn
  end

  function U.off(name, fn)
    local l = listeners[name]
    if not l then return false end
    for i = 1, #l do
      if l[i] == fn then
        table.remove(l, i)
        return true
      end
    end
    return false
  end

  function U.emit(name, ...)
    local l = listeners[name]
    if not l then return end
    local copy = {table.unpack(l)}
    for i = 1, #copy do
      local ok, err = pcall(copy[i], ...)
      if not ok then U.log("error", "listener", name, err) end
    end
  end

  -- U.guard(name, fn) -> a wrapper that runs fn under pcall. Three errors in a row stop that piece (it then does
  -- nothing and returns nil) and the third is logged once; a success resets the count. Used for every per-frame or
  -- event piece, the Kanly pattern.
  local STRIKES = 3
  function U.guard(name, fn)
    local strikes, dead = 0, false
    return function(...)
      if dead then return end
      local r = table.pack(pcall(fn, ...))
      if r[1] then
        strikes = 0
        return table.unpack(r, 2, r.n)
      end
      strikes = strikes + 1
      U.log("error", name, r[2])
      if strikes >= STRIKES then
        dead = true
        U.log("error", name, "stopped after " .. STRIKES .. " errors")
      end
    end
  end
end

-- ==== src/10_util.lua ====
-- util (P2): small helpers every fragment uses, and the per-machine preferences kept in wum.storage.
do
  function U.clamp(x, lo, hi)
    if x < lo then return lo end
    if x > hi then return hi end
    return x
  end

  function U.lerp(a, b, t) return a + (b - a) * t end

  function U.easeOutCubic(t)
    t = U.clamp(t, 0, 1) - 1
    return t * t * t + 1
  end

  -- A finite number, or nil (NaN and the infinities are refused). Used on every number that came off the wire.
  function U.num(v)
    if type(v) ~= "number" or v ~= v or v == math.huge or v == -math.huge then return nil end
    return v
  end

  -- "12:34" below an hour, "1:02:11" from an hour on; nil, NaN and negatives read as 0.
  function U.fmtTime(sec)
    sec = math.floor(U.num(sec) or 0)
    if sec < 0 then sec = 0 end
    local h, m, s = sec // 3600, (sec // 60) % 60, sec % 60
    if h > 0 then return string.format("%d:%02d:%02d", h, m, s) end
    return string.format("%d:%02d", m, s)
  end

  -- Turns control characters into spaces, strips the outer spaces and keeps at most n characters. UTF-8 aware:
  -- the bytes of a broken sequence are dropped, never cut in half. Anything but a string gives "".
  function U.trim(s, n)
    if type(s) ~= "string" then return "" end
    s = s:gsub("%c", " ")
    if not utf8.len(s) then
      local out, i, size = {}, 1, #s
      while i <= size do
        local c, len = s:byte(i), 0
        if c < 0x80 then len = 1
        elseif c >= 0xC2 and c <= 0xDF then len = 2
        elseif c >= 0xE0 and c <= 0xEF then len = 3
        elseif c >= 0xF0 and c <= 0xF4 then len = 4 end
        local ch = len > 0 and s:sub(i, i + len - 1) or ""
        if len > 0 and #ch == len and utf8.len(ch) == 1 then
          out[#out + 1] = ch
          i = i + len
        else
          i = i + 1
        end
      end
      s = table.concat(out)
    end
    s = s:match("^%s*(.-)%s*$")
    if n and utf8.len(s) > n then s = s:sub(1, utf8.offset(s, n + 1) - 1) end
    return s
  end

  -- The peer bus clock in ms; every Holo timestamp uses it, so host and peer times compare through ch:clock().
  function U.now() return wum.peer.now() end

  function U.copy(v)
    if type(v) ~= "table" then return v end
    local t = {}
    for k, x in pairs(v) do t[k] = U.copy(x) end
    return t
  end

  -- Preferences: one storage key holding a table, read once and written at most once a second after the last change
  -- (wum.storage then saves the file within 2 s).
  local PREFS_KEY = "prefs"
  local prefs, dirtyAt

  local function loadPrefs()
    if prefs then return prefs end
    local ok, v = pcall(wum.storage.get, PREFS_KEY)
    prefs = (ok and type(v) == "table") and v or {}
    return prefs
  end

  function U.pref(key, default)
    local v = loadPrefs()[key]
    if v == nil then return default end
    return v
  end

  function U.setPref(key, value)
    local p = loadPrefs()
    if type(value) ~= "table" and p[key] == value then return end
    p[key] = U.copy(value)
    dirtyAt = U.now()
  end

  function U.flushPrefs()
    if not dirtyAt then return end
    dirtyAt = nil
    local ok, err = pcall(wum.storage.set, PREFS_KEY, prefs)
    if not ok then U.log("warn", "could not save the preferences:", err) end
  end

  wum.timers.every(0.25, U.guard("prefs", function()
    if dirtyAt and U.now() - dirtyAt >= 1000 then U.flushPrefs() end
  end))
end

-- ==== src/20_config.lua ====
-- config (P2): the spice.json settings, polled every 0.5 s, and the four hotkeys they name.
do
  -- The settings of spice.json with their defaults and limits, so a hand-edited Melange.ini with a value out of range
  -- or an option that no longer exists reads as the default instead of breaking a fragment.
  local DEFS = {
    volume = {"int", 70, 0, 100},
    quality = {"enum", "720", {"360", "480", "720", "1080"}},
    hiddenMutes = {"bool", true},
    autoHideAim = {"bool", true},
    panelSide = {"enum", "right", {"right", "left"}},
    bigOnOthers = {"bool", true},
    musicOff = {"bool", true},
    uiScale = {"int", 100, 80, 130},
    keySetup = {"enum", "F6", {"F6", "Ctrl+Shift+W", "Alt+W"}},
    keyPointer = {"enum", "F7", {"F7", "Ctrl+Shift+M", "Alt+M"}},
    keyHide = {"enum", "F9", {"F9", "Ctrl+Shift+H", "Alt+H"}},
    keyPlay = {"enum", "Ctrl+Shift+P", {"Ctrl+Shift+P", "Ctrl+F9"}},
  }
  CFG.DEFS = DEFS
  -- hotkey bus name -> setting
  local HOTKEYS = {setup = "keySetup", pointer = "keyPointer", hide = "keyHide", play = "keyPlay"}
  CFG.HOTKEYS = HOTKEYS
  local KEYS, NAMES = {}, {"setup", "pointer", "hide", "play"}
  for k in pairs(DEFS) do KEYS[#KEYS + 1] = k end
  table.sort(KEYS)

  local function sanitize(key, v)
    local d = DEFS[key]
    if not d then return v end
    if d[1] == "int" then
      v = U.num(v)
      if not v then return d[2] end
      return math.floor(U.clamp(v, d[3], d[4]))
    elseif d[1] == "bool" then
      if type(v) ~= "boolean" then return d[2] end
      return v
    end
    for _, o in ipairs(d[3]) do
      if o == v then return v end
    end
    return d[2]
  end
  CFG.sanitize = sanitize

  local values = {}

  local function read(key)
    local ok, v = pcall(wum.config.get, key)
    if not ok then v = nil end
    return sanitize(key, v)
  end

  function CFG.get(key)
    local v = values[key]
    if v == nil then
      v = read(key)
      values[key] = v
    end
    return v
  end

  -- Hotkeys: the chosen key, else the setting's default, else any other option (a key another mod took raises).
  local handles, wanted, active = {}, {}, {}

  local function register(name)
    local key = CFG.get(HOTKEYS[name])
    if wanted[name] == key then return end
    wanted[name] = key
    if handles[name] then pcall(wum.ui.remove, handles[name]) end
    handles[name], active[name] = nil, nil
    local d = DEFS[HOTKEYS[name]]
    local tries = {key, d[2]}
    for _, o in ipairs(d[3]) do tries[#tries + 1] = o end
    local fire = U.guard("hotkey." .. name, function() U.emit("hotkey", name) end)
    for _, k in ipairs(tries) do
      local ok, h = pcall(wum.ui.hotkey, k, fire)
      if ok then
        handles[name], active[name] = h, k
        if k ~= key then U.log("warn", "hotkey", key, "is not available; using", k) end
        return
      end
    end
    U.log("warn", "no hotkey could be registered for", name)
  end

  -- The key actually registered for a hotkey name (it can differ from the setting after a fallback), or nil.
  function CFG.hotkeyKey(name) return active[name] end

  function CFG.poll()
    for _, key in ipairs(KEYS) do
      local v = read(key)
      if values[key] ~= v then
        local had = values[key] ~= nil
        values[key] = v
        if had then U.emit("cfg.changed", key, v) end
      end
    end
    for _, name in ipairs(NAMES) do register(name) end
  end

  CFG.poll()
  wum.timers.every(0.5, U.guard("config", CFG.poll))
end

-- ==== src/30_net.lua ====
-- net (P2): the lobby as Holo sees it, the wum.peer channel (version 1), presence and a paced outbox.
-- Bus events: "lobby.changed" (members, owner, phase or someone's presence changed), "net.enter", "net.leave",
-- "net.owner" (owner, isHost), "net.msg" (from, tbl, meta) for a message from a lobby member, "net.peer" (id, up).
do
  local CHANNEL_VERSION = 1
  local PRESENCE_TITLE = 60          -- characters of the party title in the presence (the whole table is <= 256 B)
  -- Pacing per destination, below the core limits (20 msg/s, 8 KB/s, burst 10) so queue pages never hit "rate".
  local OUT_MSGS, OUT_BYTES = 8, 6000

  local ch, openTried, openWhy = nil, -1e9, nil
  local lobby, signature = nil, ""
  local presenceMine, presenceSent = {}, nil
  local outbox = {}                  -- id -> {list = {{tbl, opts, key, bytes}}, win = start ms, n, bytes}

  ---------------------------------------------------------------- lobby

  function NET.inSession() return lobby ~= nil end
  function NET.me() return lobby and lobby.me end
  function NET.phase() return lobby and lobby.phase end
  function NET.lobby() return lobby end

  -- The party host is always the lobby owner. Without a net session this machine hosts a solo party.
  function NET.isHost() return lobby == nil or lobby.owner == lobby.me end
  function NET.hostId() return lobby and lobby.owner end

  function NET.member(id)
    if not lobby then return nil end
    for _, m in ipairs(lobby.members or {}) do
      if m.id == id then return m end
    end
  end

  function NET.name(id)
    local m = NET.member(id)
    return m and type(m.name) == "string" and U.trim(m.name, 32) or "?"
  end

  -- A presence table another member published, checked field by field: {pack = "ready"|"missing"|"downloading",
  -- progress = 0..100, party = bool, title = string, n = 0..200}. Anything else is dropped; a non-table gives nil.
  function NET.parsePresence(t)
    if type(t) ~= "table" then return nil end
    local out = {}
    if type(t.pack) == "string" then
      if t.pack == "ready" or t.pack == "missing" then
        out.pack = t.pack
      else
        local pct = t.pack:match("^downloading:(%d%d?%d?)$")
        if pct and tonumber(pct) <= 100 then out.pack, out.progress = "downloading", tonumber(pct) end
      end
    end
    if t.party == 1 or t.party == true then out.party = true end
    if out.party and type(t.title) == "string" then out.title = U.trim(t.title, PRESENCE_TITLE) end
    local n = U.num(t.n)
    if out.party and n then out.n = math.floor(U.clamp(n, 0, 200)) end
    return out
  end

  function NET.presence(id)
    if not ch then return nil end
    local ok, t = pcall(ch.presence, ch, id)
    return ok and NET.parsePresence(t) or nil
  end

  function NET.clock(id)
    if not ch then return nil end
    local ok, c = pcall(ch.clock, ch, id)
    if ok and type(c) == "table" then return c end
  end

  -- {{id, name, holo, pack, progress, rtt, me, host, party}} in lobby order; empty outside a session.
  function NET.members()
    local out = {}
    if not lobby then return out end
    for _, m in ipairs(lobby.members or {}) do
      if type(m.id) == "string" then
        local pr = (not m.me) and NET.presence(m.id) or nil
        local c = (not m.me) and NET.clock(m.id) or nil
        out[#out + 1] = {id = m.id, name = U.trim(m.name, 32), me = m.me == true, host = m.id == lobby.owner,
          holo = m.me == true or m.peer == true or pr ~= nil,
          pack = m.me and presenceMine.packState or (pr and pr.pack),
          progress = pr and pr.progress, rtt = c and U.num(c.rtt) and math.floor(c.rtt + 0.5) or nil,
          party = pr and pr.party or nil}
      end
    end
    return out
  end

  local function sign()
    if not lobby then return "" end
    local parts = {tostring(lobby.owner), tostring(lobby.phase)}
    for _, m in ipairs(lobby.members or {}) do
      local pr = (not m.me) and NET.presence(m.id) or nil
      parts[#parts + 1] = tostring(m.id) .. (m.peer and "+" or "-") .. (pr and tostring(pr.pack) .. tostring(pr.party)
        .. tostring(pr.progress) .. tostring(pr.title) .. tostring(pr.n) or "")
    end
    return table.concat(parts, "|")
  end

  function NET.refresh()
    local ok, st = pcall(wum.lobby.state)
    lobby = ok and type(st) == "table" and st or nil
    if lobby and type(lobby.members) ~= "table" then lobby.members = {} end
    local s = sign()
    if s ~= signature then
      signature = s
      U.emit("lobby.changed")
    end
  end

  ---------------------------------------------------------------- channel

  function NET.channel() return ch end
  function NET.available() return ch ~= nil, openWhy end

  local function onMessage(from, tbl, meta)
    if type(from) ~= "string" or type(tbl) ~= "table" or type(tbl.t) ~= "string" then return end
    if not NET.member(from) or from == NET.me() then return end   -- the core filters too; cheap to repeat
    U.emit("net.msg", from, tbl, type(meta) == "table" and meta or {})
  end

  local function open()
    openTried = U.now()
    local c, why = wum.peer.open{version = CHANNEL_VERSION}
    if not c then
      openWhy = why
      return
    end
    ch, openWhy = c, nil
    ch:on(U.guard("net.on", onMessage))
    ch:onPeer(U.guard("net.onPeer", function(id, up)
      if not up then outbox[id] = nil end
      U.emit("net.peer", id, up)
    end))
    presenceSent = nil
  end

  function NET.peers()
    if not ch then return {} end
    local ok, p = pcall(ch.peers, ch)
    return ok and type(p) == "table" and p or {}
  end

  function NET.reachable(id)
    for _, p in ipairs(NET.peers()) do
      if p == id then return true end
    end
    return false
  end

  -- Rough size of a table on the wire (the core's tagged binary), for the outbox pacing and the page split.
  local function sizeOf(v, depth)
    local t = type(v)
    if t == "string" then return 3 + #v end
    if t == "number" then return 9 end
    if t ~= "table" then return 1 end
    if (depth or 0) > 8 then return 1 end
    local n = 3
    for k, x in pairs(v) do n = n + sizeOf(k, 9) + sizeOf(x, (depth or 0) + 1) end
    return n
  end
  NET.sizeOf = sizeOf

  -- Sends at once: true, or false and a reason ("closed" without a channel). Unreliable when opts.reliable == false.
  function NET.send(id, tbl, opts)
    if not ch then return false, "closed" end
    local ok, r, why = pcall(ch.send, ch, id, tbl, opts)
    if not ok then return false, tostring(r) end
    return r, why
  end

  -- Queues a reliable message to one member, paced per destination. A message with a key replaces a queued one with
  -- the same key (a newer state supersedes an older one that has not left yet).
  function NET.post(id, tbl, key)
    local box = outbox[id]
    if not box then
      box = {list = {}, win = U.now(), n = 0, bytes = 0}
      outbox[id] = box
    end
    if key then
      for _, m in ipairs(box.list) do
        if m.key == key then
          m.tbl, m.bytes = tbl, sizeOf(tbl)
          return
        end
      end
    end
    box.list[#box.list + 1] = {tbl = tbl, key = key, bytes = sizeOf(tbl)}
  end

  -- Drops the queued messages to `id` whose key matches a Lua pattern (an older queue's pages).
  function NET.drop(id, pattern)
    local box = outbox[id]
    if not box then return end
    for i = #box.list, 1, -1 do
      local k = box.list[i].key
      if k and k:find(pattern) then table.remove(box.list, i) end
    end
  end

  -- NET.post to every member reachable now; returns how many.
  function NET.postAll(tbl, key)
    local peers = NET.peers()
    for _, id in ipairs(peers) do NET.post(id, tbl, key) end
    return #peers
  end

  function NET.pending(id)
    local box = outbox[id]
    return box and #box.list or 0
  end

  local function drain()
    local now = U.now()
    for id, box in pairs(outbox) do
      if now - box.win >= 1000 then box.win, box.n, box.bytes = now, 0, 0 end
      while box.list[1] and box.n < OUT_MSGS and (box.bytes + box.list[1].bytes <= OUT_BYTES or box.n == 0) do
        local m = box.list[1]
        local ok, why = NET.send(id, m.tbl)
        if not ok and why == "rate" then
          box.n = OUT_MSGS                                     -- try again in the next window
          break
        end
        table.remove(box.list, 1)
        box.n, box.bytes = box.n + 1, box.bytes + m.bytes
        if not ok then U.log("debug", "send", m.tbl.t, "failed:", why) end
      end
      if not box.list[1] then outbox[id] = nil end
    end
  end

  ---------------------------------------------------------------- presence

  -- Merges fields into this machine's presence (nil removes one) and publishes it when it changed. packState is
  -- kept for NET.members() and published as the "pack" field.
  function NET.setPresence(fields)
    for k, v in pairs(fields) do presenceMine[k] = v end
    if not ch then return end
    local pub = {pack = presenceMine.pack}
    if presenceMine.party then
      pub.party = 1
      pub.title = U.trim(presenceMine.title, PRESENCE_TITLE)
      pub.n = presenceMine.n
    end
    local s = tostring(pub.pack) .. "|" .. tostring(pub.party) .. "|" .. tostring(pub.title) .. "|" .. tostring(pub.n)
    if s == presenceSent then return end
    presenceSent = s
    pcall(ch.setPresence, ch, pub)
  end

  function NET.myPresence() return presenceMine end

  -- The pack state for the presence: "ready", "missing" or "downloading:<percent>".
  function NET.packPresence(pk)
    if type(pk) ~= "table" then return "missing" end
    if pk.state == "ready" then return "ready" end
    if pk.state == "downloading" or pk.state == "verifying" or pk.state == "installing" or pk.state == "updating" then
      return "downloading:" .. math.floor(U.clamp(U.num(pk.progress) or 0, 0, 1) * 100)
    end
    return "missing"
  end

  local function updatePack()
    local ok, pk = pcall(wum.media.pack)
    local s = NET.packPresence(ok and pk or nil)
    if s ~= presenceMine.pack then
      NET.setPresence{pack = s, packState = s:match("^%a+")}
    end
  end

  ---------------------------------------------------------------- events and tick

  local function lobbyEvent(kind)
    return U.guard("net." .. kind, function()
      NET.refresh()
      if kind == "leave" then
        outbox = {}
        U.emit("net.leave")
      elseif kind == "enter" then
        presenceSent = nil
        U.emit("net.enter")
      elseif kind == "owner" then
        outbox = {}
        U.emit("net.owner", lobby and lobby.owner, NET.isHost())
      end
    end)
  end
  wum.events.on("melange.lobby.enter", lobbyEvent("enter"))
  wum.events.on("melange.lobby.leave", lobbyEvent("leave"))
  wum.events.on("melange.lobby.owner", lobbyEvent("owner"))
  wum.events.on("melange.lobby.members", lobbyEvent("members"))
  wum.events.on("melange.lobby.phase", lobbyEvent("phase"))

  local lastRefresh = -1e9
  function NET.tick()
    local now = U.now()
    if not ch and now - openTried >= 5000 then open() end
    if now - lastRefresh >= 500 then
      lastRefresh = now
      NET.refresh()
      updatePack()
    end
    drain()
  end

  open()
  NET.refresh()
  updatePack()
  wum.timers.every(0, U.guard("net", NET.tick))
end

-- ==== src/40_party.lua ====
-- party (P2): role and phase, the host's authoritative state and the sync protocol of design 2.5 over NET.
-- Star topology: the party host is always the lobby owner; peers talk to the owner only and the owner fans out.
-- Bus events: "party.changed", "party.toast" (text, kind), "party.joinPrompt" (hostName, autoJoined),
-- "party.continuePrompt" (hostName).
do
  local PLAY_LEAD = 300              -- ms: play and resume are scheduled this far ahead so peers start together
  local HEARTBEAT = 1000             -- ms between unreliable "st" while playing
  local HI_EVERY = 10000             -- ms between "hi" until the host answers
  local HI_ACCEPT, NEED_ACCEPT = 2000, 5000   -- host: one "hi" per member per 2 s, one "need" per 5 s (N3)
  local OPEN_EVERY = 1500            -- peer: one item open per 1.5 s, coalesced to the latest item (N3)
  local NEED_EVERY = 3000            -- peer: how often it asks for a queue it is missing
  local SPEEDS = {0.5, 0.75, 1, 1.25, 1.5, 2}
  local QUALITIES = {[360] = true, [480] = true, [720] = true, [1080] = true}
  PARTY.SPEEDS = SPEEDS

  local role, phase, setupOpen = "none", "idle", false
  local player, pstate, openedId, openedUrl, loaded = nil, nil, nil, nil, false
  local hs = nil                     -- the host's state {e, i, s, p, r, a}; on a peer the last valid "st"
  local epoch = 0
  local pendingPlayAt, autoplay, ended, errorAt = nil, false, false, nil
  local lastBeat, queueDirtyAt = -1e9, nil
  local needsPack = false
  -- peer side
  local hostParty, declined, prompted, acked = false, false, false, false
  local lastHi, lastOpen, lastNeed, wantOpen = -1e9, -1e9, -1e9, nil
  -- host side: what each member told us
  local info = {}                    -- id -> {hiAt, needAt, holo, buf, err, loaded}
  local resume, musicOn = nil, false
  local applied = {}                 -- the volume and mute last sent to the player

  ---------------------------------------------------------------- small reads

  function PARTY.role() return role end
  function PARTY.active() return role ~= "none" end
  function PARTY.player() return player end
  function PARTY.state() return pstate end
  function PARTY.hostState() return hs end
  function PARTY.currentUrl() return openedUrl end
  function PARTY.currentId() return openedId end
  function PARTY.canContinue() return resume ~= nil and role == "none" and NET.isHost() end
  -- A party the lobby owner runs that this machine has not joined (or declined).
  function PARTY.partyRunning()
    if role ~= "none" or NET.isHost() then return false end
    if hostParty then return true end
    local pr = NET.presence(NET.hostId())
    return pr ~= nil and pr.party == true
  end
  function PARTY.declined() return declined end

  -- The host controls the party; before a party, the lobby owner (or anyone without a lobby) sets it up.
  function PARTY.canControl()
    if role == "host" then return true end
    return role == "none" and NET.isHost()
  end

  function PARTY.hostName()
    if not NET.inSession() or NET.isHost() then return "you" end
    return NET.name(NET.hostId())
  end

  local function toast(text, kind) U.emit("party.toast", text, kind or "info") end

  local function inSession() return NET.inSession() end

  ---------------------------------------------------------------- music, audio prefs

  local function applyMusic()
    local music = wum.audio and wum.audio.music
    if not music then return end
    local want = role ~= "none" and CFG.get("musicOff") == true
    if want == musicOn then return end
    musicOn = want
    pcall(music.suppress, want, {fade = 0.4})
  end

  local function volume() return math.floor(U.clamp(U.num(U.pref("volume", CFG.get("volume"))) or 70, 0, 100)) end
  local function userMute() return U.pref("mute", false) == true end
  local function quality()
    local q = math.tointeger(U.pref("quality")) or math.tointeger(tonumber(CFG.get("quality"))) or 720
    return QUALITIES[q] and q or 720
  end
  local function lang(key)
    local l = U.pref(key)
    if type(l) == "string" and (l:match("^%l%l%l?$") or l:match("^%l%l%l?%-%w%w%w?%w?%w?%w?%w?%w?$")) then return l end
  end

  local function effectiveMute()
    if userMute() then return true end
    return CFG.get("hiddenMutes") == true and LAYOUT.view and LAYOUT.view() == "hidden"
  end

  local function applyAudio()
    if not player then return end
    local v, m = volume(), effectiveMute()
    if applied.v ~= v then applied.v = v; player:volume(v) end
    if applied.m ~= m then applied.m = m; player:mute(m) end
  end

  function PARTY.volume() return volume() end
  function PARTY.muted() return userMute() end
  function PARTY.quality() return quality() end

  function PARTY.setVolume(v)
    v = U.num(v)
    if not v then return nil, "volume" end
    U.setPref("volume", math.floor(U.clamp(v, 0, 100) + 0.5))
    applyAudio()
    return true
  end

  function PARTY.setMute(b)
    U.setPref("mute", b == true)
    applyAudio()
    return true
  end

  function PARTY.setQuality(h)
    h = math.tointeger(h) or math.tointeger(tonumber(h))
    if not QUALITIES[h] then return nil, "quality" end
    U.setPref("quality", h)
    if player then player:quality(h) end
    return true
  end

  -- Subtitles and audio are per player and not synced; the choice is remembered by language.
  function PARTY.setTrack(kind, id)
    if kind ~= "audio" and kind ~= "sub" then return nil, "kind" end
    if not player then return nil, "no-player" end
    local ok, why = player:track(kind, id)
    if not ok then return nil, why end
    local key = kind == "audio" and "audioLang" or "subLang"
    if id == false then
      U.setPref(key, false)
    else
      for _, t in ipairs(pstate and pstate.tracks and pstate.tracks[kind] or {}) do
        if t.id == id and type(t.lang) == "string" then U.setPref(key, t.lang) end
      end
    end
    return true
  end

  ---------------------------------------------------------------- the player

  -- Closes the player. openedId/openedUrl stay: they name the item this machine is on, playing or not.
  local function closePlayer()
    if player then pcall(player.close, player) end
    player, pstate, loaded = nil, nil, false
    applied = {}
  end

  -- Opens a queue item paused at `start`. Returns the player, or nil and a reason ("wait" while a torrent's file
  -- list is still coming).
  local function openItem(it, start, paused)
    closePlayer()
    local o = {start = start or 0, paused = paused ~= false, volume = volume(), mute = effectiveMute(),
      quality = quality(), speed = hs and hs.r or 1, audioLang = lang("audioLang"), subLang = lang("subLang")}
    if it.kind == "bt" then
      local e, why = QUEUE.torrentFor(it.url)
      if not e then return nil, why end
      if e.error then return nil, "torrent" end
      if not e.files then return nil, "wait" end
      o.torrent, o.file = e.t, it.file
    else
      o.url = it.url
    end
    local p, why = wum.media.open(o)
    if not p then return nil, why end
    player, openedId, openedUrl, loaded = p, it.id, it.url, false
    applied = {v = o.volume, m = o.mute}
    if it.kind == "bt" then QUEUE.keepTorrents(it.url) end
    if LAYOUT.sizeHint then
      local w, h = LAYOUT.sizeHint()
      if w then p:size(w, h) end
    end
    return p
  end

  local function curPos()
    if player then
      local ok, st = pcall(player.state, player)
      if ok and st and U.num(st.time) then return st.time end
    end
    if hs then
      local p = hs.p
      if hs.s == "play" then p = p + math.max(0, U.now() - hs.a) / 1000 * hs.r end
      return p
    end
    return 0
  end
  PARTY.position = curPos

  ---------------------------------------------------------------- host: state and fan-out

  local function stMsg(h) return {t = "st", e = h.e, i = h.i, s = h.s, p = h.p, r = h.r, a = h.a} end

  local function broadcastState(reliable)
    if role ~= "host" or not hs or not inSession() then return end
    local m = stMsg(hs)
    if reliable == false then
      for _, id in ipairs(NET.peers()) do NET.send(id, m, {reliable = false}) end
    else
      NET.postAll(m, "st")
    end
  end

  local function setState(s, p, a)
    epoch = epoch + 1
    hs = {e = epoch, i = openedId or (hs and hs.i) or 0, s = s, p = math.max(0, p), r = hs and hs.r or 1,
      a = a or U.now()}
    broadcastState(true)
  end

  local function presence()
    if role == "host" then
      local it = QUEUE.current()
      NET.setPresence{party = true, title = it and it.title or "", n = QUEUE.count()}
    else
      NET.setPresence{party = false, title = nil, n = nil}
    end
  end

  local function sendQueue(id)
    if id then NET.drop(id, "^q%d") else for _, p in ipairs(NET.peers()) do NET.drop(p, "^q%d") end end
    for _, page in ipairs(QUEUE.pages()) do
      if id then NET.post(id, page, "q" .. page.page) else NET.postAll(page, "q" .. page.page) end
    end
  end

  local function sendTorrentInfo(id)
    local it = QUEUE.current()
    if not (it and it.kind == "bt") then return end
    local c = wum.media.classify(it.url)
    local m = {t = "bt", id = it.id, ih = c and c.infohash, f = it.file}
    if id then NET.post(id, m) else NET.postAll(m) end
  end

  local function schedulePlay(pos)
    pendingPlayAt = U.now() + PLAY_LEAD
    setState("play", pos, pendingPlayAt)
  end

  local playItem

  -- The host's next item after the current one ended or failed; past the end the party waits ("ended-item").
  local function advance()
    local nxt = QUEUE.step(1)
    if nxt then
      playItem(nxt, 0)
    else
      ended = true
      pendingPlayAt = nil
      setState("pause", curPos())
    end
  end

  function playItem(it, start)
    ended, errorAt, pendingPlayAt = false, nil, nil
    QUEUE.setCurrent(it.id)
    hs = hs or {r = 1}
    local p, why = openItem(it, start, true)
    openedId, openedUrl = it.id, it.url
    hs.i = it.id
    autoplay = true
    if not p then
      if why == "wait" then
        wantOpen = it.id                -- the torrent's file list is still coming; the tick retries
      else
        toast(why == "cache-cap" and "This file is larger than the video cache" or "Can't play this item", "error")
        errorAt = U.now()
      end
    end
    setState("pause", start or 0)
    presence()
  end

  local function startAt(it, start)
    if not it then return nil, "empty" end
    local pk = wum.media.pack()
    if not (pk and pk.state == "ready") then return nil, "pack" end
    role, resume, declined = "host", nil, false
    epoch = epoch + 1
    hs = {r = 1}
    info = {}
    applyMusic()
    if inSession() then
      NET.postAll({t = "ack", party = true, qv = QUEUE.version()}, "ack")
      sendQueue()
    end
    playItem(it, start or 0)
    U.emit("party.changed")
    return true
  end

  -- Starts the party from the queue's current item (or its first). The lobby owner only; needs the pack.
  function PARTY.start()
    if role ~= "none" then return nil, "active" end
    if not NET.isHost() then return nil, "not-host" end
    if QUEUE.count() == 0 then return nil, "empty" end
    return startAt(QUEUE.current() or QUEUE.items()[1], 0)
  end

  local function endLocal()
    closePlayer()
    openedId, openedUrl = nil, nil
    QUEUE.closeAllTorrents()
    role, hs, ended, needsPack, pendingPlayAt, autoplay, wantOpen, errorAt = "none", nil, false, false, nil, false,
      nil, nil
    applyMusic()
    presence()
    U.emit("party.changed")
  end

  -- Host: ends the party for everyone. Peer: leaves it (like declining).
  function PARTY.stop()
    if role == "host" then
      if inSession() then NET.postAll({t = "end", why = "host"}) end
      endLocal()
      return true
    elseif role == "peer" then
      return PARTY.decline()
    end
    return false
  end

  local function hostOnly()
    if role ~= "host" then return nil, "not-host" end
    if not player and not ended then return nil, "no-player" end
    return true
  end

  function PARTY.togglePlay()
    local ok, why = hostOnly()
    if not ok then return nil, why end
    autoplay = false                    -- the host decided; a pending load no longer starts by itself
    if hs.s == "play" then
      local pos = curPos()
      pendingPlayAt = nil
      if player then player:pause() end
      setState("pause", pos)
    else
      local pos = curPos()
      if ended or (pstate and pstate.eof) then
        ended, pos = false, 0
        if player then player:seek(0, "exact") end
      end
      schedulePlay(pos)
    end
    U.emit("party.changed")
    return true
  end

  -- mode "keyframes" while scrubbing (local only), "exact" on release (sent to the peers).
  function PARTY.seek(t, mode)
    local ok, why = hostOnly()
    if not ok then return nil, why end
    t = U.num(t)
    if not t or not player then return nil, "seek" end
    local dur = pstate and U.num(pstate.duration)
    if dur and dur > 0 then t = math.min(t, dur) end
    t = math.max(0, t)
    if mode == "keyframes" then
      player:seek(t, "keyframes")
      return true
    end
    player:seek(t, "exact")
    ended = false
    if pendingPlayAt then
      schedulePlay(t)                   -- the play had not started yet: keep the lead
    elseif hs.s == "play" then
      setState("play", t)
    else
      setState("pause", t)
    end
    return true
  end

  function PARTY.skip(delta)
    local d = U.num(delta)
    if not d then return nil, "seek" end
    return PARTY.seek(curPos() + d, "exact")
  end

  function PARTY.next()
    if role ~= "host" then return nil, "not-host" end
    local nxt = QUEUE.step(1)
    if not nxt then return nil, "end" end
    playItem(nxt, 0)
    return true
  end

  function PARTY.prev()
    if role ~= "host" then return nil, "not-host" end
    if player and curPos() > 5 then return PARTY.seek(0, "exact") end
    local prv = QUEUE.step(-1)
    if not prv then return PARTY.seek(0, "exact") end
    playItem(prv, 0)
    return true
  end

  -- Snaps to the nearest synced speed (0.5 to 2).
  function PARTY.setSpeed(x)
    if role ~= "host" then return nil, "not-host" end
    x = U.num(x)
    if not x then return nil, "speed" end
    local best = 1
    for _, s in ipairs(SPEEDS) do
      if math.abs(s - x) < math.abs(best - x) then best = s end
    end
    if player then player:speed(best) end
    local pos = curPos()
    hs.r = best
    setState(hs.s, pos, pendingPlayAt)
    return true
  end

  ---------------------------------------------------------------- peer side

  local function sendHost(m)
    local host = NET.hostId()
    if not host then return false end
    NET.post(host, m)
    return true
  end

  local function packReady()
    local pk = wum.media.pack()
    return pk ~= nil and pk.state == "ready"
  end

  local function hostNow()
    local c = NET.clock(NET.hostId())
    return U.now() + (c and U.num(c.offset) or 0)
  end

  -- Applies the latest host state: open the item when it changed (paced), else follow.
  local function applySt()
    if role ~= "peer" or not hs then return end
    if needsPack then return end
    if hs.i ~= openedId then
      if QUEUE.find(hs.i) then
        wantOpen = hs.i
      elseif U.now() - lastNeed >= NEED_EVERY then
        lastNeed = U.now()
        sendHost{t = "need", qv = QUEUE.version()}
      end
      return
    end
    if player then player:follow(hs, NET.hostId()) end
  end

  local function openWanted()
    local it = QUEUE.find(wantOpen)
    if not it then
      wantOpen = nil
      return
    end
    local start = hs.p
    if hs.s == "play" then start = start + math.max(0, hostNow() - hs.a) / 1000 * hs.r end
    local p, why = openItem(it, math.max(0, start), hs.s ~= "play")
    if not p then
      if why == "wait" then return end   -- the torrent's file list is still coming
      wantOpen = nil
      if why == "pack" then
        needsPack = true                  -- opened again once the pack is ready
      else
        openedId, openedUrl = it.id, it.url -- this item failed here; do not retry it on every "st"
        toast(why == "first-use-in-match" and "Torrent items can start only in the menus or the lobby"
          or "Can't play this item here", "error")
        sendHost{t = "buf", b = false, i = it.id, p = 0, ok = false}
      end
      U.emit("party.changed")
      return
    end
    wantOpen = nil
    QUEUE.setCurrent(it.id)
    p:follow(hs, NET.hostId())
  end

  function PARTY.join()
    if role ~= "none" then return nil, "active" end
    if NET.isHost() or not PARTY.partyRunning() then return nil, "no-party" end
    role, declined = "peer", false
    U.setPref("autoJoin", true)
    needsPack = not packReady()
    applyMusic()
    if QUEUE.count() == 0 or not hs then
      lastNeed = U.now()
      sendHost{t = "need", qv = QUEUE.version()}
    end
    applySt()
    U.emit("party.changed")
    return true
  end

  -- "Not now": leaves the running party (or refuses the prompt) and remembers it; the next party prompts again.
  function PARTY.decline()
    declined = true
    U.setPref("autoJoin", false)
    if role == "peer" then endLocal() end
    U.emit("party.changed")
    return true
  end

  local function hostRunning()
    if hostParty then return end
    hostParty = true
    if role ~= "none" or declined or prompted then return end
    prompted = true
    if U.pref("autoJoin", true) ~= false then
      PARTY.join()
      U.emit("party.joinPrompt", PARTY.hostName(), true)
    else
      U.emit("party.joinPrompt", PARTY.hostName(), false)
    end
  end

  -- A new owner that had the queue continues where the old host stopped.
  function PARTY.continueParty()
    if not PARTY.canContinue() then return nil, "nothing" end
    local snap = resume
    local cur = QUEUE.load(snap.snap)
    local it = (cur and QUEUE.find(cur)) or QUEUE.items()[1]
    if not it then
      resume = nil
      return nil, "empty"
    end
    local r = snap.rate or 1
    local ok, why = startAt(it, it.id == cur and snap.time or 0)
    if ok and r ~= 1 then PARTY.setSpeed(r) end
    return ok, why
  end

  -- Loads the queue stored by the last party this machine hosted (only while idle).
  function PARTY.restoreLastQueue()
    if role ~= "none" or not PARTY.canControl() then return nil, "active" end
    local snap = U.pref("lastQueue")
    if type(snap) ~= "table" then return nil, "nothing" end
    QUEUE.load(snap)
    return true
  end

  ---------------------------------------------------------------- message validation

  -- A "st" from the host, checked: returns the clean state or nil.
  function PARTY.checkSt(m)
    if type(m) ~= "table" then return nil end
    local e, i, p, r, a = m.e, m.i, U.num(m.p), U.num(m.r), U.num(m.a)
    if math.type(e) ~= "integer" or e < 0 or math.type(i) ~= "integer" or i < 0 then return nil end
    if m.s ~= "play" and m.s ~= "pause" then return nil end
    if not p or p < 0 or p > 1e7 or not r or r < 0.25 or r > 4 or not a then return nil end
    return {e = e, i = i, s = m.s, p = p, r = r, a = a}
  end

  local function newer(a, b)
    if not b then return true end
    if a.e ~= b.e then return a.e > b.e end
    return a.a >= b.a
  end

  local function fromHost(from, m)
    local t = m.t
    if t == "ack" then
      acked = true
      if m.party == true then
        hostRunning()
      elseif hostParty or role == "peer" then
        hostParty = false
        if role == "peer" then endLocal() end
      end
    elseif t == "q" then
      local done = QUEUE.acceptPage(m)
      if done then
        hostRunning()
        applySt()
      end
    elseif t == "st" then
      local st = PARTY.checkSt(m)
      if not st or not newer(st, hs) then return end
      hs = st
      hostRunning()
      applySt()
    elseif t == "bt" then
      local it = QUEUE.find(m.id)
      local c = it and wum.media.classify(it.url)
      if c and c.infohash == m.ih then QUEUE.setFile(m.id, m.f) end
    elseif t == "end" then
      local was = role == "peer"
      hostParty, declined, prompted = false, false, false
      if was then
        endLocal()
        toast("The host ended the watch party")
      end
      U.emit("party.changed")
    end
  end

  local function fromMember(from, m)
    local t = m.t
    local now = U.now()
    local mi = info[from]
    if not mi then
      mi = {hiAt = -1e9, needAt = -1e9}
      info[from] = mi
    end
    if t == "hi" then
      if now - mi.hiAt < HI_ACCEPT then return end
      mi.hiAt = now
      mi.holo = U.trim(m.holo, 16)
      NET.post(from, {t = "ack", party = role == "host", qv = QUEUE.version()}, "ack")
      if role == "host" then
        sendQueue(from)
        if hs then NET.post(from, stMsg(hs), "st") end
        sendTorrentInfo(from)
      end
    elseif t == "need" then
      if role ~= "host" or now - mi.needAt < NEED_ACCEPT then return end
      mi.needAt = now
      sendQueue(from)
      if hs then NET.post(from, stMsg(hs), "st") end
    elseif t == "buf" then
      if type(m.b) ~= "boolean" then return end
      mi.buf = m.b
      mi.err = m.ok == false
      if m.ok == true then mi.loaded = true end
    end
  end

  U.on("net.msg", function(from, m)
    if from == NET.hostId() and not NET.isHost() then
      fromHost(from, m)
    elseif NET.isHost() and inSession() then
      fromMember(from, m)
    end
  end)

  U.on("net.peer", function(id, up)
    if id == NET.hostId() and not NET.isHost() then
      acked = false
      if up then lastHi = -1e9 end
    elseif info[id] and not up then
      info[id].buf = false
    end
  end)

  ---------------------------------------------------------------- lobby changes

  local function resetPeerSide()
    hostParty, declined, prompted, acked = false, false, false, false
    lastHi, wantOpen = -1e9, nil
    info = {}
    if role == "none" then hs = nil end
    -- A peer forgets the host's queue version, so the next host's pages are taken whatever their number. An owner
    -- keeps its own counter (a peer's mirror never shares it after this reset).
    if not NET.isHost() then QUEUE.resetVersion() end
  end

  -- The lobby changed hands: the party ends for everyone. Every machine keeps the queue and where it was, and a new
  -- owner with Holo is offered "Continue party".
  U.on("net.owner", function(owner, isHost)
    local had = role ~= "none" or hostParty
    if had then
      resume = {snap = QUEUE.snapshot(), time = curPos(), rate = hs and hs.r or 1}
      if role ~= "none" then endLocal() end
      toast("The host left; the watch party ended", "warn")
    end
    resetPeerSide()
    if had and isHost then
      U.emit("party.continuePrompt", PARTY.hostName())
    elseif not isHost then
      resume = nil
    end
    U.emit("party.changed")
  end)

  U.on("net.leave", function()
    if role ~= "none" then endLocal() end
    resetPeerSide()
    resume = nil
    U.emit("party.changed")
  end)

  U.on("net.enter", function()
    -- A solo party ends when this machine joins someone else's lobby; a lobby it owns keeps it.
    if role == "host" and not NET.isHost() then
      endLocal()
      toast("Your watch party ended: you joined a lobby", "info")
    end
    resetPeerSide()
  end)

  ---------------------------------------------------------------- queue and layout changes

  U.on("queue.changed", function(kind)
    if PARTY.canControl() then U.setPref("lastQueue", QUEUE.snapshot()) end
    if role ~= "host" or kind == "current" then return end   -- peers take the current item from st.i
    queueDirtyAt = queueDirtyAt or U.now()
    if ended and QUEUE.step(1) then advance() end
  end)

  -- The host removed the item that is playing: the next one at its place plays, an empty queue ends the party.
  U.on("queue.removed", function(it, index)
    if role ~= "host" or it.id ~= openedId then return end
    local items = QUEUE.items()
    if #items == 0 then
      if inSession() then NET.postAll({t = "end", why = "empty"}) end
      endLocal()
      return
    end
    local nxt = items[index] or items[#items]
    playItem(nxt, 0)
  end)

  U.on("layout.size", function(w, h)
    if player and w then player:size(w, h) end
  end)

  U.on("cfg.changed", function(key, v)
    if key == "musicOff" then
      applyMusic()
    elseif key == "volume" then
      U.setPref("volume", v)
      applyAudio()
    elseif key == "quality" then
      PARTY.setQuality(v)
    end
  end)

  ---------------------------------------------------------------- media events

  wum.events.on("melange.media", U.guard("party.media", function(ev)
    if role == "none" or not player then return end
    local ty = ev.type
    if ty == "loaded" then
      loaded = true
      local it = QUEUE.find(openedId)
      local d = U.num(ev.duration)
      if it and d and d > 0 then it.duration = d end
      if role == "host" and autoplay then
        autoplay = false
        schedulePlay(curPos())
      elseif role == "peer" then
        sendHost{t = "buf", b = false, i = openedId, p = curPos(), ok = true}
        if hs and hs.i == openedId then player:follow(hs, NET.hostId()) end
      end
    elseif ty == "buffering" then
      if role == "peer" then sendHost{t = "buf", b = ev.on == true, i = openedId, p = curPos(), ok = true} end
    elseif ty == "ended" then
      if ev.reason == "eof" then
        if role == "host" then advance() end
      elseif ev.reason == "error" then
        if role == "host" then
          toast("Can't play this item; skipping it", "error")
          errorAt = U.now()
        else
          sendHost{t = "buf", b = false, i = openedId, p = curPos(), ok = false}
        end
      end
    elseif ty == "error" then
      if role == "peer" then
        toast("Can't play this here", "error")
        sendHost{t = "buf", b = false, i = openedId, p = curPos(), ok = false}
      else
        toast("Can't play this item; skipping it", "error")
        errorAt = U.now()
      end
    elseif ty == "helper" and ev.state == "dead" then
      toast("The video player stopped working", "error")
    end
    U.emit("party.changed")
  end))

  ---------------------------------------------------------------- setup panel state, peers list, pack

  function PARTY.setupOpen() return setupOpen end
  function PARTY.setSetup(open)
    setupOpen = open == true
    U.emit("party.changed")
  end
  function PARTY.toggleSetup() PARTY.setSetup(not setupOpen) end

  -- The other members: {{id, name, state = "ready"|"buffering"|"nopack"|"noholo"|"error", drift}}.
  function PARTY.peers()
    local out = {}
    for _, m in ipairs(NET.members()) do
      if not m.me then
        local mi = info[m.id] or {}
        local state = "ready"
        if not m.holo then state = "noholo"
        elseif m.pack and m.pack ~= "ready" then state = "nopack"
        elseif mi.err then state = "error"
        elseif mi.buf then state = "buffering" end
        out[#out + 1] = {id = m.id, name = m.name, state = state, host = m.host, rtt = m.rtt}
      end
    end
    return out
  end

  function PARTY.pack() return wum.media.pack() end

  -- Call it from the click handler of the consent button: the click is the consent (2 s window).
  function PARTY.installPack()
    local ok, why = wum.media.install()
    if not ok and why ~= "ready" then
      local text = {gesture = "Click Download again", blocked = "Downloads are turned off in Melange.ini",
        ["unsupported-os"] = "The media pack needs 64-bit Windows", disabled = "Media is turned off in Melange.ini",
        busy = "The download is already running"}
      toast(text[why] or ("Could not start the download (" .. tostring(why) .. ")"), "error")
    end
    return ok, why
  end

  function PARTY.consentText()
    local pk = wum.media.pack() or {}
    return string.format("Holo plays videos with Melange's media pack: a %d MB download (%d MB on disk) from "
      .. "Melange's GitHub releases (github.com/JaminB/melange), installed once into Documents\\Melange\\media and "
      .. "checked against hashes built into Melange. YouTube items use yt-dlp; torrent items share your IP address "
      .. "with the swarm.", math.floor(U.num(pk.downloadMB) or 95), math.floor(U.num(pk.diskMB) or 300))
  end

  ---------------------------------------------------------------- tick

  local lastPackPoll = -1e9

  local function computePhase()
    if role == "none" then return setupOpen and "setup" or "idle" end
    if needsPack then return "needs-pack" end
    if ended then return "ended-item" end
    if not player or not pstate then return "loading" end
    if pstate.eof then return "ended-item" end
    if not loaded and not (U.num(pstate.duration) and pstate.duration > 0) then return "loading" end
    if pstate.buffering then return "buffering" end
    if pendingPlayAt then return "loading" end
    if pstate.paused then return "paused" end
    return "playing"
  end

  -- The phase is computed on read, so it is right straight after a call such as stop(); the tick emits changes.
  function PARTY.phase() return computePhase() end

  function PARTY.tick()
    local now = U.now()
    if player then
      local ok, st = pcall(player.state, player)
      pstate = ok and st or nil
    else
      pstate = nil
    end

    if role == "host" then
      if pendingPlayAt and now >= pendingPlayAt then
        pendingPlayAt = nil
        if player then player:play() end
      end
      if wantOpen and not player then
        local it = QUEUE.find(wantOpen)
        if it and openItem(it, hs and hs.p or 0, true) then wantOpen = nil end
      end
      if errorAt and now - errorAt >= 2000 then
        errorAt = nil
        advance()
      end
      if hs and hs.s == "play" and not pendingPlayAt and loaded and now - lastBeat >= HEARTBEAT then
        lastBeat = now
        hs.p, hs.a = curPos(), now
        broadcastState(false)
      end
      if queueDirtyAt and now - queueDirtyAt >= 300 then
        queueDirtyAt = nil
        if inSession() then sendQueue() end
        presence()
      end
    elseif inSession() and not NET.isHost() then
      local host = NET.hostId()
      if not acked and now - lastHi >= HI_EVERY and NET.reachable(host) then
        lastHi = now
        NET.send(host, {t = "hi", v = 1, pack = NET.myPresence().pack or "missing", holo = VERSION})
      end
      if role == "peer" then
        if needsPack and now - lastPackPoll >= 500 then
          lastPackPoll = now
          if packReady() then
            needsPack = false
            applySt()
          end
        end
        if wantOpen and now - lastOpen >= OPEN_EVERY then
          lastOpen = now
          openWanted()
        end
      end
    end

    applyAudio()
    local ph = computePhase()
    if ph ~= phase then
      phase = ph
      U.emit("party.changed")
    end
  end

  presence()
  wum.timers.every(0, U.guard("party", PARTY.tick))
end

-- ==== src/45_queue.lua ====
-- queue (P2): the host's play queue, its wire pages, the peers' mirror of it, and the torrents its items need.
-- Items are {id, kind = "yt"|"bt", url (canonical), file (torrent file index), title, duration, live}.
-- Bus events: "queue.changed" (with "current" when only the current item changed: no new version, nothing to send),
-- "queue.pick" (token, files, name) for the torrent file picker, "queue.picked" (item), "queue.removed" (item, index).
do
  local MAX_ITEMS = 200
  local TITLE = 120
  local PAGE_BYTES = 7000            -- a reliable message is at most 8 KB
  local MAX_PAGES = 64
  local MAX_TORRENTS = 3             -- the core allows 4 per mod; one stays free for a new magnet's file list

  local items, cur, qv, nextId = {}, nil, 0, 1
  local picks, nextToken = {}, 1
  local torrents = {}                -- canonical magnet -> {t = handle, files = list|nil, waiting = {fn...}}
  local partial = nil                -- the peer's pages being assembled: {qv, pages, got = {page -> items}, n, cur}

  local function changed()
    qv = qv + 1
    U.emit("queue.changed")
  end

  function QUEUE.items() return items end
  function QUEUE.version() return qv end
  function QUEUE.count() return #items end

  function QUEUE.indexOf(id)
    for i, it in ipairs(items) do
      if it.id == id then return i end
    end
  end

  function QUEUE.find(id)
    local i = QUEUE.indexOf(id)
    return i and items[i]
  end

  function QUEUE.current() return cur and QUEUE.find(cur) or nil end
  function QUEUE.currentIndex() return cur and QUEUE.indexOf(cur) or nil end

  -- Sets the current item. It is not a new queue version: the peers follow the host's st.i, so a new item never
  -- resends the whole queue.
  function QUEUE.setCurrent(id)
    if id ~= nil and not QUEUE.find(id) then return false end
    if cur ~= id then
      cur = id
      U.emit("queue.changed", "current")
    end
    return true
  end

  -- The item delta steps from the current one (1 = next, -1 = previous), or nil past either end. Without a current
  -- item, next is the first.
  function QUEUE.step(delta)
    local i = QUEUE.currentIndex()
    if not i then return delta > 0 and items[1] or nil end
    return items[i + delta]
  end

  local function canEdit()
    if not PARTY.canControl() then return false end
    return true
  end

  local function append(it)
    if #items >= MAX_ITEMS then return nil, "full" end
    it.id = nextId
    nextId = nextId + 1
    items[#items + 1] = it
    return it
  end

  ---------------------------------------------------------------- torrents

  local function countTorrents()
    local n = 0
    for _ in pairs(torrents) do n = n + 1 end
    return n
  end

  local function openTorrent(url)
    local e = torrents[url]
    if e and not e.closed then return e end
    if countTorrents() >= MAX_TORRENTS then QUEUE.keepTorrents(PARTY.currentUrl()) end
    e = {waiting = {}}
    local t, why = wum.media.torrent(url, U.guard("queue.torrent", function(res)
      if type(res) ~= "table" then return end
      if type(res.files) == "table" then e.files, e.name = res.files, res.name end
      if res.error then e.error = tostring(res.error) end
      local w = e.waiting
      e.waiting = {}
      for _, fn in ipairs(w) do fn(e) end
    end))
    if not t then return nil, why end
    e.t = t
    torrents[url] = e
    return e
  end

  -- The open torrent for a magnet (opened if needed): entry {t, files, name, error}, or nil, reason.
  function QUEUE.torrentFor(url) return openTorrent(url) end

  function QUEUE.closeTorrent(url)
    local e = torrents[url]
    if not e then return end
    torrents[url] = nil
    e.closed = true
    if e.t then pcall(e.t.close, e.t) end
  end

  -- Closes every torrent except the one of `keepUrl` and those still waiting for a file pick.
  function QUEUE.keepTorrents(keepUrl)
    local busy = {}
    for _, p in pairs(picks) do busy[p.url] = true end
    for url in pairs(torrents) do
      if url ~= keepUrl and not busy[url] then QUEUE.closeTorrent(url) end
    end
  end

  function QUEUE.closeAllTorrents()
    for token in pairs(picks) do picks[token] = nil end
    for url in pairs(torrents) do QUEUE.closeTorrent(url) end
  end

  -- The video files of a torrent, largest first (the picker lists nothing else, design S3).
  function QUEUE.videoFiles(files)
    local out = {}
    for _, f in ipairs(type(files) == "table" and files or {}) do
      if type(f) == "table" and f.video == true and math.type(f.index) == "integer" then
        out[#out + 1] = {index = f.index, path = U.trim(f.path, 240), size = U.num(f.size) or 0}
      end
    end
    table.sort(out, function(a, b)
      if a.size ~= b.size then return a.size > b.size end
      return a.index < b.index
    end)
    return out
  end

  local function baseName(path)
    return (tostring(path):match("([^/\\]+)$") or tostring(path)):gsub("%.%w+$", "")
  end

  local function addTorrentItem(url, file, title)
    local it, why = append{kind = "bt", url = url, file = file, title = U.trim(title, TITLE), duration = 0}
    if not it then return nil, why end
    changed()
    -- Keep the file list of the newest magnet for a quick start, but never hold more than the cap.
    if countTorrents() > MAX_TORRENTS - 1 and url ~= PARTY.currentUrl() then QUEUE.closeTorrent(url) end
    return it
  end

  function QUEUE.pickFile(token, index)
    local p = picks[token]
    if not p then return nil, "unknown" end
    for _, f in ipairs(p.files) do
      if f.index == index then
        picks[token] = nil
        local it, why = addTorrentItem(p.url, index, baseName(f.path))
        if it then U.emit("queue.picked", it) end
        return it ~= nil, why
      end
    end
    return nil, "file"
  end

  function QUEUE.cancelPick(token)
    local p = picks[token]
    if not p then return false end
    picks[token] = nil
    local used = PARTY.currentUrl() == p.url
    for _, it in ipairs(items) do used = used or it.url == p.url end
    if not used then QUEUE.closeTorrent(p.url) end
    return true
  end

  local function onTorrentFiles(token, e)
    local p = picks[token]
    if not p then return end
    if e.error or not e.files then
      picks[token] = nil
      QUEUE.closeTorrent(p.url)
      U.emit("party.toast", "This torrent could not be read", "error")
      return
    end
    local vids = QUEUE.videoFiles(e.files)
    if #vids == 0 then
      picks[token] = nil
      QUEUE.closeTorrent(p.url)
      U.emit("party.toast", "No video file in this torrent", "warn")
      return
    end
    p.files, p.name = vids, U.trim(e.name or p.name, TITLE)
    if #vids == 1 then
      QUEUE.pickFile(token, vids[1].index)
    else
      U.emit("queue.pick", token, vids, p.name)
    end
  end

  ---------------------------------------------------------------- adding

  local function fillTitle(url, res)
    if type(res) ~= "table" or type(res.items) ~= "table" or type(res.items[1]) ~= "table" then return end
    local r = res.items[1]
    for _, it in ipairs(items) do
      if it.url == url and it.untitled then
        it.untitled = nil
        it.title = U.trim(r.title, TITLE)
        if it.title == "" then it.title = "YouTube video" end
        it.duration = U.num(r.duration) and math.max(0, r.duration) or 0
        changed()
      end
    end
  end

  local function addPlaylist(res)
    if type(res) ~= "table" then return end
    if res.error then
      U.emit("party.toast", res.error == "private" and "That playlist is private" or "Could not list that playlist",
        "error")
      return
    end
    local n = 0
    for _, r in ipairs(type(res.items) == "table" and res.items or {}) do
      local c = type(r) == "table" and type(r.url) == "string" and wum.media.classify(r.url)
      if c and c.kind == "youtube" and c.id then
        local it = append{kind = "yt", url = c.url, title = U.trim(r.title, TITLE),
          duration = U.num(r.duration) and math.max(0, r.duration) or 0, live = c.live or nil}
        if not it then break end
        if it.title == "" then it.title = "YouTube video" end
        n = n + 1
      end
    end
    if n > 0 then changed() end
    U.emit("party.toast", n > 0 and ("Added " .. n .. " videos") or "That playlist has no playable videos",
      n > 0 and "info" or "warn")
  end

  -- Adds what the user typed or pasted: true (a playlist or a torrent finishes later), or nil and a reason:
  -- "unsupported-url", "not-host", "full", or a wum.media reason ("busy", "first-use-in-match", ...).
  function QUEUE.add(text)
    if type(text) ~= "string" then return nil, "unsupported-url" end
    local c = wum.media.classify(text)
    if not c then return nil, "unsupported-url" end
    if not canEdit() then return nil, "not-host" end
    if #items >= MAX_ITEMS then return nil, "full" end
    if c.kind == "magnet" then
      local e, why = openTorrent(c.url)
      if not e then return nil, why end
      local token = nextToken
      nextToken = nextToken + 1
      picks[token] = {url = c.url, name = c.name or "Torrent", files = {}}
      if e.files or e.error then
        onTorrentFiles(token, e)
      else
        e.waiting[#e.waiting + 1] = function(x) onTorrentFiles(token, x) end
      end
      return true
    end
    if c.id then
      local it = append{kind = "yt", url = c.url, title = "YouTube video", duration = 0, untitled = true,
        live = c.live or nil}
      changed()
      local url = it.url
      wum.media.resolve(url, U.guard("queue.title", function(res) fillTitle(url, res) end))
      return true
    end
    local id, why = wum.media.resolve(c.url, U.guard("queue.playlist", addPlaylist))
    if not id then return nil, why end
    return true
  end

  function QUEUE.remove(id)
    if not canEdit() then return nil, "not-host" end
    local i = QUEUE.indexOf(id)
    if not i then return nil, "unknown" end
    local it = table.remove(items, i)
    if cur == id then cur = nil end
    if it.kind == "bt" then
      local used = false
      for _, x in ipairs(items) do used = used or x.url == it.url end
      if not used and PARTY.currentUrl() ~= it.url then QUEUE.closeTorrent(it.url) end
    end
    U.emit("queue.removed", it, i)
    changed()
    return true
  end

  function QUEUE.move(id, delta)
    if not canEdit() then return nil, "not-host" end
    local i = QUEUE.indexOf(id)
    if not i then return nil, "unknown" end
    local j = U.clamp(i + delta, 1, #items)
    if j == i then return false end
    local it = table.remove(items, i)
    table.insert(items, j, it)
    changed()
    return true
  end

  function QUEUE.clear()
    items, cur = {}, nil
    changed()
  end

  ---------------------------------------------------------------- snapshots (resume) and wire pages

  function QUEUE.snapshot() return {items = U.copy(items), cur = cur} end

  -- Loads a snapshot as this machine's own queue (a new host continuing, or the stored last queue). Items are
  -- checked again like wire items and get new ids; returns the new id of the snapshot's current item.
  function QUEUE.load(snap)
    items, cur = {}, nil
    local newCur
    for _, it in ipairs(type(snap) == "table" and type(snap.items) == "table" and snap.items or {}) do
      local w = QUEUE.checkWire({id = 1, k = it.kind, u = it.url, f = it.file, ti = it.title, d = it.duration})
      if w then
        local n = append(w)
        if not n then break end
        if it.id == snap.cur then newCur = n.id end
      end
    end
    cur = newCur
    changed()
    return newCur
  end

  local function toWire(it)
    return {id = it.id, k = it.kind, u = it.url, f = it.file, ti = it.title, d = it.duration}
  end

  -- The queue as "q" messages: {{t = "q", qv, page, pages, items, cur}, ...}, each under PAGE_BYTES. An empty queue
  -- is one page with no items.
  function QUEUE.pages()
    local pages, page, bytes = {}, {}, 0
    for _, it in ipairs(items) do
      local w = toWire(it)
      local b = NET.sizeOf(w)
      if #page > 0 and (bytes + b > PAGE_BYTES or #page >= 100) then
        pages[#pages + 1] = page
        page, bytes = {}, 0
      end
      page[#page + 1] = w
      bytes = bytes + b
    end
    pages[#pages + 1] = page
    local out = {}
    for i, p in ipairs(pages) do
      out[i] = {t = "q", qv = qv, page = i, pages = #pages, items = p, cur = cur}
    end
    return out
  end

  -- One wire item, checked: the url is classified again and must match the kind, the title is trimmed, a torrent
  -- item needs a file index. Returns a queue item (without an id) or nil.
  function QUEUE.checkWire(w)
    if type(w) ~= "table" or math.type(w.id) ~= "integer" or w.id < 1 then return nil end
    if type(w.u) ~= "string" or #w.u > 4096 then return nil end
    local c = wum.media.classify(w.u)
    if not c then return nil end
    local it = {kind = w.k, url = c.url, title = U.trim(w.ti, TITLE), duration = 0}
    local d = U.num(w.d)
    if d and d > 0 then it.duration = math.min(d, 1e7) end
    if w.k == "yt" then
      if c.kind ~= "youtube" or not c.id then return nil end
      it.live = c.live or nil
    elseif w.k == "bt" then
      if c.kind ~= "magnet" or math.type(w.f) ~= "integer" or w.f < 0 or w.f > 100000 then return nil end
      it.file = w.f
    else
      return nil
    end
    if it.title == "" then it.title = it.kind == "bt" and "Torrent" or "YouTube video" end
    return it
  end

  -- A "q" page from the host (the peer's mirror). Returns true once every page of that version arrived and the
  -- mirror was replaced, false while pages are missing, nil for a malformed or stale page.
  function QUEUE.acceptPage(m)
    local v, page, pages = m.qv, m.page, m.pages
    if math.type(v) ~= "integer" or math.type(page) ~= "integer" or math.type(pages) ~= "integer" then return nil end
    if pages < 1 or pages > MAX_PAGES or page < 1 or page > pages or type(m.items) ~= "table" then return nil end
    if v == qv and not partial then return nil end      -- already have it
    if not partial or partial.qv ~= v or partial.pages ~= pages then
      partial = {qv = v, pages = pages, got = {}, n = 0}
    end
    if not partial.got[page] then
      local list = {}
      for _, w in ipairs(m.items) do
        local it = QUEUE.checkWire(w)
        if it then
          it.id = w.id
          list[#list + 1] = it
        end
        if #list >= MAX_ITEMS then break end
      end
      partial.got[page], partial.n = list, partial.n + 1
    end
    if page == pages or math.type(m.cur) == "integer" then partial.cur = m.cur end
    if partial.n < pages then return false end
    local new, seen = {}, {}
    for p = 1, pages do
      for _, it in ipairs(partial.got[p]) do
        if #new < MAX_ITEMS and not seen[it.id] then
          seen[it.id] = true
          new[#new + 1] = it
        end
      end
    end
    items, qv = new, v
    cur = (math.type(partial.cur) == "integer" and seen[partial.cur]) and partial.cur or nil
    partial = nil
    U.emit("queue.changed")
    return true
  end

  -- The peer side: forget the host's version so the next host's pages are taken whatever their number.
  function QUEUE.resetVersion()
    partial = nil
    qv = -1
  end

  -- Sets a mirrored item's file (the host's "bt" message).
  function QUEUE.setFile(id, file)
    local it = QUEUE.find(id)
    if not it or it.kind ~= "bt" or math.type(file) ~= "integer" or file < 0 then return false end
    if it.file ~= file then
      it.file = file
      U.emit("queue.changed")
    end
    return true
  end
end

-- ==== src/50_layout.lua ====
-- layout (P2): where the player sits (design 2.3 and 2.4), the view (full, pill, hidden), the auto-hide gate while
-- this machine aims and fires, and the fades. It never draws and never claims regions; P3 draws from these rects.
-- Bus events: "layout.view" (view), "layout.anchor" (anchor), "layout.size" (w, h) once an animation settles.
do
  local ANIM, CTRL_FADE, FADE = 0.35, 0.25, 0.15     -- seconds
  local FADED = 0.3                                    -- alpha under a pause menu or the weapon panel
  local MARGIN, FRAME, PANEL_PAD, TAG, BAR = 24, 9, 12, 44, 64
  -- Pixels at 1080p between the top margin and the corner player, so the wind disc stays visible. Measured from a
  -- match screenshot in check B3; 0 until then.
  local WIND_OFFSET = 0
  local SETTLE_QUIET, FLIGHT_FAILSAFE = 0.6, 8         -- the flight gate (seconds)
  local AIM_GROUPS = {WormAiming = true, WormFirstPersonAiming = true, Fire = true, UtilityFire = true}
  LAYOUT.WIND_OFFSET = WIND_OFFSET

  local view = U.pref("view", "full")
  if view ~= "full" and view ~= "pill" and view ~= "hidden" then view = "full" end
  local lastShown = U.pref("lastShown", "full") == "pill" and "pill" or "full"
  local anchor = "corner"
  local cur, from, animT = nil, nil, nil     -- displayed rect {x0, y0, x1, y1}; animation start rect and time
  local winW, winH = 0, 0
  local alpha, alphaTarget, ctrlAlpha = 1, 1, 1
  local faded, autoHidden = false, false
  local sentW, sentH = nil, nil
  -- the auto-hide gate
  local fireDown, inFlight, flightAt, boomAt = false, false, 0, nil

  local function now() return U.now() / 1000 end

  function LAYOUT.view() return view end
  function LAYOUT.anchor() return anchor end
  function LAYOUT.alpha() return alpha end
  function LAYOUT.controlsAlpha() return ctrlAlpha * alpha end
  function LAYOUT.autoHidden() return autoHidden end
  function LAYOUT.faded() return faded end
  function LAYOUT.side() return CFG.get("panelSide") == "left" and "left" or "right" end
  function LAYOUT.animating() return animT ~= nil end

  -- Interactive means P3 may claim regions: shown, not faded, not auto-hidden, and fully faded in.
  function LAYOUT.interactive()
    return view ~= "hidden" and not autoHidden and not faded and alpha >= 0.95
  end

  local function baseScale(h) return U.clamp(h / 1080, 0.6, 2.5) end
  function LAYOUT.scale()
    local _, h = wum.render.windowSize()
    return baseScale(h) * CFG.get("uiScale") / 100
  end

  function LAYOUT.setView(v)
    if v ~= "full" and v ~= "pill" and v ~= "hidden" then return false end
    if v ~= "hidden" then
      lastShown = v
      U.setPref("lastShown", v)
    end
    if v == view then return true end
    view = v
    U.setPref("view", v)
    U.emit("layout.view", v)
    return true
  end

  -- The hide hotkey: full or pill <-> hidden (back to the last shown view).
  function LAYOUT.toggleHide()
    if view == "hidden" then return LAYOUT.setView(lastShown) end
    return LAYOUT.setView("hidden")
  end

  ---------------------------------------------------------------- rects

  -- The corner video rect for a window: 22 % of min(W, H*16/9) wide (times uiScale), 16:9, inside a 9 px frame
  -- with a 24 px margin, below the wind disc.
  function LAYOUT.cornerRect(W, H, side)
    local s0 = baseScale(H)
    local k = CFG.get("uiScale") / 100
    local s = s0 * k
    local vw = 0.22 * math.min(W, H * 16 / 9) * k
    local vh = vw * 9 / 16
    local y0 = MARGIN * s + WIND_OFFSET * s0 + FRAME * s
    local x0
    if side == "left" then x0 = MARGIN * s + FRAME * s else x0 = W - MARGIN * s - FRAME * s - vw end
    return x0, y0, x0 + vw, y0 + vh
  end

  -- The half panel: video, title tag above and control bar below, vertically centred in one half of the window.
  -- Returns the video rect and the panel rect (tag and bar included).
  function LAYOUT.halfRects(W, H, side)
    local s = baseScale(H) * CFG.get("uiScale") / 100
    local m, pad, tag, bar = MARGIN * s, PANEL_PAD * s, TAG * s, BAR * s
    local px0, px1
    if side == "left" then px0, px1 = m, W / 2 - m else px0, px1 = W / 2 + m, W - m end
    local vw = (px1 - px0) - 2 * pad
    local vh = vw * 9 / 16
    local room = H - 2 * m - tag - bar
    if vh > room then
      vh = math.max(room, 1)
      vw = vh * 16 / 9
      local cx = (px0 + px1) / 2
      px0, px1 = cx - vw / 2 - pad, cx + vw / 2 + pad
    end
    local total = tag + vh + bar
    local py0 = (H - total) / 2
    local vx0 = px0 + pad
    local vy0 = py0 + tag
    return {vx0, vy0, vx0 + vw, vy0 + vh}, {px0, py0, px1, py0 + total}
  end

  local function target()
    local side = LAYOUT.side()
    if anchor == "half" then
      local v = LAYOUT.halfRects(winW, winH, side)
      return v
    end
    return {LAYOUT.cornerRect(winW, winH, side)}
  end

  function LAYOUT.rect()
    local r = cur or target()
    return r[1], r[2], r[3], r[4]
  end

  function LAYOUT.panelRect()
    local _, p = LAYOUT.halfRects(winW, winH, LAYOUT.side())
    return p[1], p[2], p[3], p[4]
  end

  -- The minimised pill, at the top of the player's side.
  function LAYOUT.pillRect()
    local s = baseScale(winH) * CFG.get("uiScale") / 100
    local w, h = 300 * s, 56 * s
    local y0 = MARGIN * s + WIND_OFFSET * baseScale(winH)
    if LAYOUT.side() == "left" then return MARGIN * s, y0, MARGIN * s + w, y0 + h end
    return winW - MARGIN * s - w, y0, winW - MARGIN * s, y0 + h
  end

  -- What the decoder should render once the rect settled: 422x238 (corner) or 960x540 (half, at most 1280x720),
  -- scaled like the layout.
  function LAYOUT.sizeHint()
    local s = baseScale(winH > 0 and winH or 1080) * CFG.get("uiScale") / 100
    if anchor == "half" then
      local w = math.min(960 * s, 1280)
      return math.floor(w + 0.5), math.floor(w * 9 / 16 + 0.5)
    end
    return math.floor(422 * s + 0.5), math.floor(238 * s + 0.5)
  end

  ---------------------------------------------------------------- the rules

  local function inMatch()
    if wum.game.inMatch then
      local ok, v = pcall(wum.game.inMatch)
      if ok and v then return true end
    end
    return NET.phase() == "match"
  end

  local function onlineMatch()
    if not inMatch() then return false end
    return NET.inSession() or wum.game.online() == true
  end

  local function turnInfo()
    local ok, t = pcall(wum.game.turn)
    return ok and type(t) == "table" and t or nil
  end

  local function uiFlags()
    local ok, u = pcall(wum.game.ui)
    return ok and type(u) == "table" and u or {}
  end

  -- The anchor the table of design 2.4 gives now, or nil to keep the last one (between turns, the Ready? intro).
  function LAYOUT.ruleAnchor()
    if not onlineMatch() then return "corner" end
    local t, u = turnInfo(), uiFlags()
    if not t or u.readyIntro or t.team == nil then return nil end
    if t.mine then return "corner" end
    return CFG.get("bigOnOthers") and "half" or "corner"
  end

  local function myTurn(t)
    return inMatch() and t ~= nil and t.mine == true and t.team ~= nil
  end

  local function aiming()
    local ok, g = pcall(wum.input.groups)
    if not ok or type(g) ~= "table" then return false end
    for _, name in ipairs(g) do
      if AIM_GROUPS[name] then return true end
    end
    return false
  end

  local function resetFlight() inFlight, boomAt = false, nil end

  -- Auto-hide: my turn and (an aiming group is active, fire is held, or a shot is in flight). Audio is never muted
  -- by it (I3).
  function LAYOUT.gate()
    if not CFG.get("autoHideAim") then return false end
    local t = turnInfo()
    if not myTurn(t) then return false end
    local n = now()
    if inFlight then
      if (boomAt and n - boomAt >= SETTLE_QUIET) or n - flightAt >= FLIGHT_FAILSAFE then resetFlight() end
    end
    return fireDown or inFlight or aiming()
  end

  local function turnStarted()
    resetFlight()
    fireDown = false
  end

  wum.events.on("Input.FirePressed", U.guard("layout.fire", function() fireDown = true end))
  wum.events.on("Input.FireReleased", U.guard("layout.fire", function() fireDown = false end))
  wum.events.on("Weapon.Fired", U.guard("layout.fired", function()
    inFlight, flightAt, boomAt, fireDown = true, now(), nil, false
  end))
  wum.events.on("Explosion", U.guard("layout.boom", function()
    if inFlight then boomAt = now() end
  end))
  wum.events.on("Timer.StartRetreatTimer", U.guard("layout.retreat", resetFlight))
  wum.events.on("melange.turn", U.guard("layout.turn", turnStarted))
  wum.events.on("GameLogic.Turn.Started", U.guard("layout.turn", turnStarted))
  wum.events.on("melange.match.end", U.guard("layout.matchEnd", turnStarted))

  ---------------------------------------------------------------- update

  local function sameRect(a, b)
    return a and b and a[1] == b[1] and a[2] == b[2] and a[3] == b[3] and a[4] == b[4]
  end

  local function approach(v, goal, rate, dt)
    if v < goal then return math.min(goal, v + rate * dt) end
    return math.max(goal, v - rate * dt)
  end

  function LAYOUT.update(dt)
    dt = U.clamp(U.num(dt) or 0, 0, 0.25)
    local W, H = wum.render.windowSize()
    local resized = W ~= winW or H ~= winH
    winW, winH = W, H

    local want = LAYOUT.ruleAnchor() or anchor
    if want ~= anchor then
      from = cur and {cur[1], cur[2], cur[3], cur[4]} or nil
      anchor = want
      animT = from and 0 or nil
      ctrlAlpha = 0
      U.emit("layout.anchor", anchor)
    end
    local to = target()
    if resized or not cur then
      cur, animT, from = to, nil, nil
    elseif animT then
      animT = animT + dt
      local k = U.easeOutCubic(animT / ANIM)
      cur = {U.lerp(from[1], to[1], k), U.lerp(from[2], to[2], k), U.lerp(from[3], to[3], k),
        U.lerp(from[4], to[4], k)}
      if animT >= ANIM then cur, animT, from = to, nil, nil end
    elseif not sameRect(cur, to) then
      -- a setting changed the target (side, scale): animate there too
      from, animT, ctrlAlpha = cur, 0, 0
    end

    if not animT then
      ctrlAlpha = approach(ctrlAlpha, 1, 1 / CTRL_FADE, dt)
      local w, h = LAYOUT.sizeHint()
      if w ~= sentW or h ~= sentH then
        sentW, sentH = w, h
        U.emit("layout.size", w, h)
      end
    end

    local t, u = turnInfo(), uiFlags()
    faded = u.pause == true or (u.weaponPanel == true and myTurn(t))
    local gate = LAYOUT.gate()
    if gate and not autoHidden then
      autoHidden = true
    elseif not gate and autoHidden then
      autoHidden = false
    end
    if view == "hidden" or autoHidden then alphaTarget = 0
    elseif faded then alphaTarget = FADED
    else alphaTarget = 1 end
    alpha = approach(alpha, alphaTarget, 1 / FADE, dt)
  end

  LAYOUT.update(0)                  -- rects are valid before the first frame
  local last = U.now()
  wum.timers.every(0, U.guard("layout", function()
    local n = U.now()
    LAYOUT.update((n - last) / 1000)
    last = n
  end))
end

